function bestTeamOutput(skill: number[], stamina: number[], k: number): number {
  let best = 0;
  const go = (i: number, left: number, sum: number, low: number): void => {
    if (left === 0) { best = Math.max(best, sum * low); return; }
    if (skill.length - i < left) return;
    go(i + 1, left - 1, sum + skill[i], Math.min(low, stamina[i]));
    go(i + 1, left, sum, low);
  };
  go(0, k, 0, Infinity);
  return best;
}

